select jsonb_build_object('project','qvplwejffhjvxaypmjut','at',statement_timestamp(),'rows',(select jsonb_agg(jsonb_build_object('workId',w.id,'title',w.title,'editions',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'language',e.language,'isbn',e.isbn_13,'format',m.format,'reviewStatus',m.review_status,'boundCover',m.cover_url) order by e.id),'[]') from public.editions e left join public.catalog_edition_metadata m on m.edition_id=e.id where e.work_id=w.id and lower(e.language) in('nl','nld','dut')),'approvedNlSummary',exists(select 1 from public.catalog_work_descriptions t where t.work_id=w.id and t.language='nl' and t.review_status='approved')) order by w.id) from public.works w where w.id in(1,6,17,117,185,1220,1229,1243,1287,1299,1300,1305,1326,1360,1369,1383,2146,2675,2685,2716,2722,2723,2732,4316,8410,8425,9282,10032))) as readiness;
